: 1px solid var(--hair); }\n.rk-correction-progress .rk-progress-copy { min-width: 0; overflow-wrap: anywhere; }\n.rk-correction-progress [data-progress-stage] { display: block; font-weight: 700; letter-spacing: .3px; }\n.rk-correction-progress [data-progress-message] { color: var(--ink2); margin: 2px 0 0; font-size: 11px; line-height: 1.5; }\n.rk-correction-progress [data-progress-attempt] { display: block; color: var(--muted); font: 10px/1.5 var(--font-num); }\n.rk-correction-progress .rk-progress-glyph {\n  display: block;\n  width: 9px;\n  height: 9px;\n  margin-top: 4px;\n  box-sizing: border-box;\n  border: 1px solid currentColor;\n}\n.rk-correction-progress[data-active='true'] .rk-progress-glyph {\n  border-width: 2px;\n  border-right-color: transparent;\n  animation: rk-correction-turn 1.1s steps(4, end) infinite;\n}\n.rk-correction-progress[data-state='applied'] .rk-progress-glyph,\n.rk-correction-progress[data-state='unchanged'] .rk-progress-glyph { background: currentColor; }\n.rk-correction-progress[data-state='failed'] .rk-progress-glyph { border: 0; width: auto; height: auto; margin-top: 0; font-weight: 900; font-size: 15px; }\n.rk-correction-progress[data-state='failed'] .rk-progress-glyph::before { content: '!'; }\n.rk-correction-progress .rk-progress-actions { display: flex; gap: 5px; flex-wrap: wrap; justify-content: end; max-width: 128px; }\n.rk-correction-progress .rk-progress-actions button {\n  min-height: 32px;\n  padding: 4px 7px;\n  border: 1px solid var(--hair);\n  border-radius: 0;\n  background: var(--card2);\n  color: var(--ink);\n  font: 11px/1.5 var(--font-ui);\n  cursor: pointer;\n  touch-action: manipulation;\n}\n.rk-correction-progress .rk-progress-actions button:disabled { opacity: .45; cursor: default; }\n.rk-correction-progress .rk-progress-actions button:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }\n.rk-correction-progress [hidden] { display: none !important; }\n@keyframes rk-correction-turn { to { transform: rotate(360deg); } }\n@media (max-width: 360px) {\n  .rk-correction-progress { gap: 6px; padding: 8px; }\n  .rk-correction-progress .rk-progress-actions { max-width: 66px; }\n  .rk-correction-progress .rk-progress-actions button { width: 100%; min-height: 36px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .rk-correction-progress[data-active='true'] .rk-progress-glyph { animation: none; border-right-color: currentColor; }\n}\n\n/* 选拔赛使用现有黑白终端色板；表单在窄屏自动换行。 */\n.rk-t-panel, .rk-t-form { min-width: 0; overflow-wrap: anywhere; }\n.rk-t-actions { display: flex; flex-wrap: wrap; gap: 7px; margin: 10px 0; }\n.rk-t-panel button, .rk-t-form button { border: 1px solid var(--hair); border-radius: 0; padding: 7px 10px; min-height: 36px; color: var(--ink); background: var(--card2); font: inherit; cursor: pointer; }\n.rk-t-panel button:hover, .rk-t-form button:hover { border-color: var(--ink); }\n.rk-t-panel button:disabled, .rk-t-form button:disabled { opacity: .5; cursor: default; }\n.rk-t-form fieldset { border: 0; min-width: 0; margin: 0; padding: 0; }\n.rk-t-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 140px), 1fr)); gap: 10px; }\n.rk-t-field { display: grid; gap: 5px; min-width: 0; margin: 9px 0; font-size: 12px; }\n.rk-t-field input, .rk-t-field select, .rk-t-field textarea { width: 100%; min-width: 0; box-sizing: border-box; padding: 8px; color: var(--ink); background: var(--card2); border: 1px solid var(--hair); border-radius: 0; font: inherit; }\n.rk-t-field textarea { resize: vertical; }\n.rk-t-panel :is(button, summary):focus-visible, .rk-t-form :is(input, select, textarea, button, summary):focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }\n.rk-t-message { border-left: 3px solid var(--ink); padding: 7px 9px; background: var(--card2); }\n.rk-t-match { padding: 12px 0; border-bottom: 1px solid var(--hair); }\n.rk-t-match:last-child { border-bottom: 0; }\n.rk-t-match-head { display: flex; align-items: baseline; flex-wrap: wrap; justify-content: space-between; gap: 8px; font-size: 11px; }\n.rk-t-pair { font-weight: 700; line-height: 1.6; margin: 8px 0; }\n.rk-t-pair span { font-weight: 400; color: var(--muted); }\n.rk-t-table-wrap { width: 100%; overflow-x: auto; }\n.rk-t-table { width: 100%; border-collapse: collapse; font-size: 12px; text-align: left; }\n.rk-t-table :is(th, td) { padding: 9px 6px; border-bottom: 1px solid var(--hair); vertical-align: top; overflow-wrap: anywhere; }\n.rk-t-table small { display: block; color: var(--muted); font-weight: 400; margin-top: 4px; }\n\n/* 玩家照片共用图片加载回退；设置表单独立刷新，不重建其他配置输入。 */\n.rk-player-avatar { position: relative; display: block; width: 100%; height: 100%; overflow: hidden; }\n.rk-player-avatar .rk-avatar-initial { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }\n.rk-player-avatar .rk-avatar-image { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center top; }\n.rk-player-avatar.rk-avatar-ready .rk-avatar-initial { display: none; }\n.rk-player-avatar.rk-avatar-failed .rk-avatar-image { display: none; }\n.rk-player-avatar.rk-avatar-failed .rk-avatar-initial { display: flex; }\n.rk-player-portrait-settings { min-width: 0; overflow-wrap: anywhere; }\n.rk-player-portrait-settings p { font-size: 12px; line-height: 1.6; color: var(--muted); margin: 7px 0; }\n.rk-player-portrait-settings label { display: grid; gap: 6px; margin: 12px 0; font-size: 12px; }\n.rk-player-portrait-settings textarea { width: 100%; min-width: 0; box-sizing: border-box; padding: 9px; color: var(--ink); background: var(--card2); border: 1px solid var(--hair); border-radius: 0; font: inherit; }\n.rk-player-portrait-settings textarea { resize: vertical; }\n.rk-player-portrait-heading { display: flex; gap: 12px; align-items: center; }\n.rk-player-portrait-heading > div:last-child { min-width: 0; }\n.rk-player-portrait-heading .card-avatar { width: 64px; height: 64px; flex: 