n.rk-calendar-lore-heading button:disabled{opacity:.55;cursor:wait}\n.rk-calendar-lore-heading button:focus-visible,.rk-calendar-story-button:focus-visible,#rk-calendar-story button:focus-visible{outline:2px solid var(--ink);outline-offset:3px}\n.rk-calendar-lore-note{font-size:11px;color:var(--muted);overflow-wrap:anywhere}\n.rk-calendar-story-button{display:block;width:100%;text-align:left;margin:6px 0;overflow-wrap:anywhere}\n.rk-calendar-story-button small{display:block;color:var(--muted);font-size:10px;margin-top:3px}\n.rk-calendar-undated summary{cursor:pointer;font-weight:700;padding:8px 0}\n.rk-calendar-undated[open]{padding-bottom:8px}\n#rk-calendar-story{box-sizing:border-box;width:calc(100% - 24px);max-width:680px;max-height:calc(100% - 24px);margin:auto;padding:14px;border:2px solid var(--ink);border-radius:0;background:var(--card);color:var(--ink);overflow:auto;overscroll-behavior:contain;font:12px/1.65 var(--font-ui)}\n#rk-calendar-story::backdrop{background:rgba(0,0,0,.65)}\n.rk-calendar-story-header{position:sticky;top:-14px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;background:var(--card);padding:10px 0;border-bottom:1px solid var(--hair);z-index:1}\n#rk-calendar-story-title{font:700 14px/1.5 var(--font-title);margin:0;min-width:0;overflow-wrap:anywhere}\n.rk-calendar-story-header button{flex-shrink:0}\n#rk-calendar-story-source{font-size:11px;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere}\n#rk-calendar-story-content{margin:12px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font:inherit;color:var(--ink2)}\n\n/* ===== 破军 LIME 互换通讯录样式 ===== */\n.lime-contact-list{display:flex;flex-direction:column;gap:8px;margin-bottom:12px}\n.lime-contact-card{display:flex;align-items:center;cursor:pointer;gap:10px}\n.lime-badge-added{display:inline-block;padding:1px 5px;font:700 9px var(--font-ui);border:1px solid var(--ink);background:var(--card2);color:var(--ink);border-radius:0;margin-left:4px}\n.lime-badge-unadded{display:inline-block;padding:1px 5px;font:9px var(--font-ui);border:1px dashed var(--hair);background:transparent;color:var(--muted);border-radius:0;margin-left:4px}\n.lime-contact-card.muted-card{border-style:dashed;opacity:0.8}\n.gba-btn-chat{padding:4px 9px;font:11px var(--font-ui);border:1px solid var(--ink);background:var(--surface);color:var(--ink);border-radius:0;cursor:pointer;white-space:nowrap}\n.gba-btn-chat:hover{background:var(--ink);color:var(--screen)}\n.gba-btn-action{padding:7px 10px;font:12px var(--font-ui);border:1px solid var(--hair);background:var(--surface);color:var(--ink);text-align:left;border-radius:0;cursor:pointer}\n.gba-btn-action:hover{border-color:var(--ink);background:var(--card2)}\n.gba-lime-hint{margin-top:8px;padding:8px 10px;background:var(--card2);border-left:3px solid var(--hair);font-size:11.5px;color:var(--ink2);line-height:1.6}\n.gba-lime-hint strong{color:var(--ink)}\n\n\n\n/* 副 API 表单随手机宽度收拢；长正文、提示词与补丁均留在卡片内。 */\n.rk-correction { min-width: 0; }\n.rk-correction p { color: var(--muted); font-size: 12px; line-height: 1.6; margin: 8px 0; overflow-wrap: anywhere; }\n.rk-correction label { display: grid; min-width: 0; gap: 5px; margin: 10px 0; font-size: 12px; }\n.rk-correction input, .rk-correction textarea, .rk-correction select { display: block; width: 100%; min-width: 0; box-sizing: border-box; padding: 9px; border: 1px solid var(--hair); border-radius: 3px; background: var(--card2); color: var(--ink); font: inherit; line-height: 1.5; }\n.rk-correction textarea { resize: vertical; }\n.rk-correction textarea[readonly] { font-size: 11px; }\n.rk-correction-model { display: flex; align-items: end; gap: 8px; }\n.rk-correction-model label { flex: 1; }\n.rk-correction-model button { flex: none; margin-bottom: 10px; white-space: nowrap; }\n.rk-correction-fields { display: grid; grid-template-columns: minmax(0, 1fr) 100px; gap: 10px; }\n.rk-correction-fold { margin: 12px 0; padding: 10px; border: 1px solid var(--hair); background: var(--card); }\n.rk-correction-fold summary { cursor: pointer; font-size: 12px; font-weight: 600; line-height: 1.6; }\n.rk-correction-actions { display: flex; gap: 8px; flex-wrap: wrap; margin: 10px 0; }\n.rk-correction button { padding: 8px 10px; background: var(--card2); color: var(--ink); border: 1px solid var(--hair); border-radius: 3px; font: 12px var(--font-ui); line-height: 1.5; cursor: pointer; }\n.rk-correction button.rk-correction-primary { background: var(--ink); color: var(--screen); border-color: var(--ink); }\n.rk-correction button:disabled { opacity: .45; cursor: default; }\n.rk-correction :is(input, textarea, select, button, summary):focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }\n.rk-correction pre { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 260px; overflow: auto; margin: 0; padding: 10px; background: var(--card2); font-size: 11px; line-height: 1.5; }\n.rk-correction [data-status] { min-height: 2.4em; }\n@media (max-width: 360px) { .rk-correction-fields { grid-template-columns: minmax(0, 1fr) 85px; gap: 8px; } .rk-correction-fold { padding: 8px; } }\n\n/* 自动开关用原生复选框，避免通用输入框样式将它撑满一行。 */\n.rk-correction label.rk-correction-auto { display: flex; align-items: center; gap: 8px; }\n.rk-correction .rk-correction-auto input { width: 16px; height: 16px; flex: none; margin: 0; padding: 0; accent-color: var(--ink); }\n.rk-correction [data-auto-status] { border-left: 2px solid var(--ink); padding-left: 8px; }\n\n/* 七星剑斗祭：沿用终端外壳，赛事大屏在内部独立滚动。 */\n.rk-arena-entry{display:flex;flex-direction:column;gap:8px;width:100%;padding:18px;margin-bottom:16px;text-align:left;color:var(--ink);background:var(--card);border:1px solid var(--hair);cursor:pointer}\n.rk-arena-entry>span{font-size:16px;font-weight:700}\n.rk-arena-entry>small{color:var(--muted);line-height:1.5}\n.rk-arena-locked>p{margin:0 0 10px;color:var(--muted)}\n.rk-arena-preview{flex:none;padding:10px 16px;border-bottom:1px solid var(--hair);background:var(--card);font-weight:700;line-height:1.5}\n.rk-arena-preview>small{font-weight:400;color:var(--muted)}\n#arena-body{display:flex;flex:1;min-height:0;padding:0;overflow:hidden}\n#rk-tournament-frame{display:block;width:100%;height:100%;min-height:0;flex:1;border:0;background:#0a0a0a}\n\u003c/style>\n\u003cstyle>\n/* Color-block status module. Kept inside the dossier; shell and wheel keep their theme. */\n#blazer-body.gba-status {\n  --gba-ink: #1b2748;\n  --gba-navy: #2b4773;\n  --gba-navy-light: #3d608b;\n  --gba-paper: #fff3d6;\n  --gba-paper-shade: #e9dcb9;\n  --gba-muted: #526076;\n  --gba-gold: #efbd4f;\n  --gba-teal: #319e8e;\n  --gba-teal-light: #82d1ad;\n  --gba-red: #c85b46;\n  --ink: var(--gba-ink);\n  --ink2: #35425b;\n  --muted: var(--gba-muted);\n  --card: var(--gba-paper);\n  --card2: var(--gba-paper-shade);\n  --hair: #82908f;\n  --sky: #205f79;\n  --crimson: var(--gba-red);\n  --press: var(--gba-paper-shade);\n  color: var(--gba-ink);\n  background: #223759;\n  padding: 2px 0 16px;\n  font-size: 13px;\n  line-height: 1.65;\n  overflow-wrap: anywhere;\n  scrollbar-color: var(--gba-gold) var(--gba-ink);\n  color-scheme: light;\n}\n\n#blazer-body.gba-status *,\n#blazer-body.gba-status *::before,\n#blazer-body.gba-status *::after {\n  box-sizing: border-box;\n}\n\n#blazer-body.gba-status .card1 {\n  margin: 12px 10px;\n  padding: 12px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-paper);\n  color: var(--gba-ink);\n  box-shadow: 2px 2px 0 #14203a;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .ct {\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n  border-bottom: 2px solid var(--gba-gold);\n  padding: 6px 9px;\n  margin: 12px 0 9px;\n  font-family: var(--font-ui);\n  font-size: 12px;\n  font-weight: 700;\n  line-height: 1.5;\n  letter-spacing: .5px;\n}\n\n#blazer-body.gba-status .card1 > .ct:first-child {\n  margin: -12px -12px 12px;\n}\n\n#blazer-body.gba-status .card-avatar {\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  border: 2px solid var(--gba-ink);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .card-rank-badge {\n  display: inline-block;\n  vertical-align: middle;\n  min-width: 27px;\n  margin-left: 3px;\n  padding: 2px 5px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 13px/1.3 var(--font-num);\n  text-align: center;\n  text-shadow: none;\n  white-space: nowrap;\n}\n\n/* 觉醒是独立布尔状态，使用文字和边框区分，不伪装成等级奖励。 */\n#blazer-body.gba-status .gba-awakening {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin: 10px 0;\n  padding: 7px 9px;\n  border: 1px solid #82908f;\n  background: var(--gba-paper-shade);\n  color: var(--gba-muted);\n  font-size: 12px;\n}\n\n#blazer-body.gba-status .gba-awakening strong {\n  color: var(--gba-ink);\n  font-weight: 700;\n}\n\n#blazer-body.gba-status .gba-awakening[data-awakened='true'] {\n  border-left: 4px solid var(--gba-red);\n}\n\n/* A navy field keeps the chart distinct from the paper explanation beneath it. */\n#blazer-body.gba-status .radar-container {\n  background: var(--gba-navy);\n  border: 2px solid var(--gba-ink);\n  padding: 12px 0;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .radar-svg {\n  display: block;\n  width: min(100%, 320px);\n  max-height: none;\n  height: auto;\n  overflow: visible;\n}\n\n#blazer-body.gba-status .radar-web,\n#blazer-body.gba-status .radar-web-spoke,\n#blazer-body.gba-status .radar-spoke {\n  stroke: #91abc0;\n  stroke-width: 1;\n  stroke-opacity: .7;\n}\n\n#blazer-body.gba-status .radar-web { fill: none; }\n\n#blazer-body.gba-status .radar-polygon {\n  fill: var(--gba-teal);\n  fill-opacity: .72;\n  stroke: var(--gba-gold);\n  stroke-width: 2.2;\n  filter: none;\n}\n\n#blazer-body.gba-status .radar-point {\n  fill: var(--gba-paper);\n  stroke: var(--gba-ink);\n  stroke-width: 2;\n}\n\n#blazer-body.gba-status .radar-label {\n  fill: var(--gba-paper);\n  font-family: var(--font-ui);\n  font-size: 10px;\n  font-weight: 600;\n}\n\n#blazer-body.gba-status .radar-rank-badge {\n  fill: var(--gba-gold);\n  font: 700 12px var(--font-num);\n}\n\n#blazer-body.gba-status .radar-legend,\n#blazer-body.gba-status .gba-note {\n  color: var(--gba-muted);\n  font-size: 12px;\n  line-height: 1.65;\n  margin: 9px 0 0;\n}\n\n#blazer-body.gba-status .noble-art-block {\n  margin-top: 10px;\n  padding: 9px 10px;\n  border: 1px solid #a1a58f;\n  border-left: 4px solid var(--gba-teal);\n  border-radius: 0;\n  background: var(--gba-paper-shade);\n}\n\n#blazer-body.gba-status .noble-art-title {\n  color: var(--gba-ink);\n  font: 700 13px/1.6 var(--font-ui);\n  flex-wrap: wrap;\n}\n\n#blazer-body.gba-status .noble-art-desc {\n  color: var(--ink2);\n  font-size: 12px;\n  line-height: 1.7;\n}\n\n/* Native details provides one full-width, keyboard-operable contact control. */\n#blazer-body.gba-status .roster-list {\n  padding: 10px;\n  gap: 12px;\n}\n\n#blazer-body.gba-status details.roster-card {\n  display: block;\n  padding: 0;\n  margin: 0;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-paper);\n  color: var(--gba-ink);\n  box-shadow: 2px 2px 0 #14203a;\n  cursor: auto;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .gba-contact-summary {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 11px 10px;\n  min-height: 68px;\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n  list-style: none;\n  cursor: pointer;\n  touch-action: manipulation;\n}\n\n#blazer-body.gba-status .gba-contact-summary::-webkit-details-marker { display: none; }\n#blazer-body.gba-status .gba-contact-summary::marker { content: ''; }\n\n#blazer-body.gba-status .gba-contact-summary:hover {\n  background: var(--gba-navy-light);\n}\n\n#blazer-body.gba-status .gba-contact-summary:focus-visible {\n  outline: 3px solid var(--gba-gold);\n  outline-offset: -3px;\n}\n\n#blazer-body.gba-status .gba-contact[open] > .gba-contact-summary {\n  border-bottom: 3px solid var(--gba-gold);\n}\n\n#blazer-body.gba-status .roster-ava {\n  width: 42px;\n  height: 44px;\n  flex: 0 0 42px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 24px/1 var(--font-title);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .roster-ava.rk-knight-avatar {\n  width: 60px;\n  height: 80px;\n  flex-basis: 60px;\n  border: 0;\n  background: transparent;\n  color: var(--gba-ink);\n}\n\n#blazer-body.gba-status .rk-avatar-initial {\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  border: 2px solid var(--gba-ink);\n}\n\n/* 名册标题始终是深蓝色；只提高复用黑色盾边的对比，不改人物色彩。 */\n#blazer-body.gba-status .rk-avatar-frame { filter: invert(1); }\n\n#blazer-body.gba-status .roster-info {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n\n#blazer-body.gba-status .roster-name {\n  color: inherit;\n  font-size: 14px;\n  font-weight: 700;\n  line-height: 1.7;\n}\n\n#blazer-body.gba-status .roster-device {\n  color: var(--ink2);\n  font-size: 12px;\n  line-height: 1.7;\n  white-space: normal;\n  overflow-wrap: anywhere;\n}\n\n#blazer-body.gba-status .gba-contact-summary .roster-device {\n  color: #dae6e5;\n  margin-top: 3px;\n}\n\n#blazer-body.gba-status .gba-disclosure {\n  flex: 0 0 auto;\n  color: var(--gba-gold);\n  font: 700 12px/1.5 var(--font-ui);\n  text-align: center;\n}\n\n#blazer-body.gba-status .gba-disclosure::before {\n  content: '▸';\n  display: block;\n  font-size: 17px;\n  line-height: 1;\n}\n\n#blazer-body.gba-status .gba-contact[open] .gba-disclosure::before { content: '▾'; }\n\n#blazer-body.gba-status .gba-contact-body {\n  padding: 12px;\n  color: var(--gba-ink);\n  background: var(--gba-paper);\n  min-width: 0;\n}\n\n#blazer-body.gba-status .gba-contact-body > .roster-device + .roster-device {\n  margin-top: 6px;\n}\n\n#blazer-body.gba-status .gba-contact-body dl {\n  display: grid;\n  grid-template-colu