n-outgoing: var(--surface);\n  --rk-lime-accent: var(--ink);\n  --rk-lime-on-accent: var(--surface);\n  --rk-lime-focus: var(--ring);\n  color-scheme: inherit;\n  color: var(--rk-lime-text);\n  background: var(--rk-lime-list);\n  font-family: var(--font-ui);\n  container-type: inline-size;\n}\n\n#scr-lime *, #scr-lime *::before, #scr-lime *::after { box-sizing: border-box; }\n#scr-lime [hidden] { display: none !important; }\n#scr-lime :is(button, input, textarea) { font-family: inherit; }\n#scr-lime button { cursor: pointer; touch-action: manipulation; }\n#scr-lime button:disabled { cursor: default; opacity: .55; }\n#scr-lime :is(button, summary, input, textarea):focus-visible {\n  outline: 2px solid var(--rk-lime-focus);\n  outline-offset: 2px;\n}\n\n#scr-lime .rk-lime-header {\n  display: flex;\n  align-items: center;\n  flex-wrap: nowrap;\n  flex: none;\n  gap: 8px;\n  min-height: 64px;\n  padding: 6px 10px;\n  color: var(--rk-lime-text);\n  background: var(--rk-lime-paper);\n  border-bottom: 1px solid var(--rk-lime-line);\n  box-shadow: none;\n}\n#scr-lime .rk-lime-header .back,\n#scr-lime .rk-lime-profile-toggle {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  width: 44px;\n  min-width: 44px;\n  height: 44px;\n  padding: 0;\n  color: var(--rk-lime-text);\n  background: transparent;\n  border: 0;\n  border-radius: 12px;\n  font-size: 22px;\n}\n#scr-lime .rk-lime-profile-toggle { width: auto; padding: 0 10px; font-size: 13px; }\n#scr-lime .rk-lime-header .back:hover,\n#scr-lime .rk-lime-profile-toggle:hover { color: var(--rk-lime-text); background: var(--rk-lime-hover); }\n#scr-lime .rk-lime-profile-toggle[aria-expanded=\"true\"] { color: var(--rk-lime-accent); background: var(--rk-lime-soft); }\n#scr-lime .rk-lime-heading { display: flex; flex: 1; flex-direction: column; gap: 2px; min-width: 0; }\n#scr-lime .rk-lime-heading .t {\n  margin: 0;\n  font: 700 16px/1.35 var(--font-ui);\n  color: var(--rk-lime-text);\n  letter-spacing: 0;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n#scr-lime .rk-lime-heading .sub {\n  margin: 0;\n  color: var(--rk-lime-muted);\n  font: 11px/1.4 var(--font-ui);\n  overflow-wrap: anywhere;\n}\n#scr-lime #lime-body.rk-lime-body {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  padding: 0;\n  background: var(--rk-lime-list);\n  overflow: hidden;\n}\n\n/* Search and tabs stay visible while the conversation list scrolls. */\n#scr-lime .rk-lime-search { flex: none; padding: 12px 16px 8px; background: var(--rk-lime-paper); }\n#scr-lime .rk-lime-search input {\n  display: block;\n  width: 100%;\n  height: 44px;\n  padding: 0 14px;\n  border: 1px solid var(--rk-lime-line);\n  border-radius: 12px;\n  background: var(--rk-lime-soft);\n  color: var(--rk-lime-text);\n  font-size: 16px;\n  appearance: none;\n}\n#scr-lime .rk-lime-search input::placeholder { color: var(--rk-lime-muted); opacity: 1; }\n#scr-lime .rk-lime-tabs {\n  display: flex;\n  flex: none;\n  gap: 16px;\n  padding: 0 16px;\n  background: var(--rk-lime-paper);\n  border-bottom: 1px solid var(--rk-lime-line);\n}\n#scr-lime .rk-lime-tabs button {\n  position: relative;\n  min-width: 44px;\n  min-height: 44px;\n  padding: 8px 2px;\n  border: 0;\n  border-bottom: 3px solid transparent;\n  background: transparent;\n  color: var(--rk-lime-muted);\n  font-size: 13px;\n  font-weight: 600;\n}\n#scr-lime .rk-lime-tabs button[aria-selected=\"true\"] { color: var(--rk-lime-accent); border-bottom-color: var(--rk-lime-accent); }\n#scr-lime .rk-lime-list {\n  flex: 1;\n  min-height: 0;\n  padding: 4px 0 12px;\n  background: var(--rk-lime-paper);\n  overflow-x: hidden;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  -webkit-overflow-scrolling: touch;\n}\n#scr-lime .rk-lime-contact {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  width: 100%;\n  min-height: 84px;\n  margin: 0;\n  padding: 12px 16px;\n  border: 0;