-lime-line); font-size: 18px; }\n\n#scr-lime .rk-lime-room {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  width: 100%;\n  height: 100%;\n  min-width: 0;\n  min-height: 0;\n  background: var(--rk-lime-chat);\n  overflow: hidden;\n}\n#scr-lime .rk-lime-profile {\n  flex: none;\n  margin: 0;\n  padding: 0 12px;\n  border-bottom: 1px solid var(--rk-lime-line);\n  background: var(--rk-lime-paper);\n  color: var(--rk-lime-text);\n  font-size: 12px;\n}\n#scr-lime .rk-lime-profile > summary { min-height: 44px; padding: 12px 0; cursor: pointer; font-weight: 600; }\n#scr-lime .rk-lime-profile[open] { max-height: 34%; overflow-y: auto; overscroll-behavior: contain; }\n#scr-lime .rk-lime-profile .lime-chat-profile { gap: 10px; padding: 10px 0; }\n#scr-lime .rk-lime-profile .card1 { margin: 8px 0; padding: 10px; border-radius: 10px; border: 1px solid var(--rk-lime-line); box-shadow: none; }\n#scr-lime .rk-lime-timeline {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  gap: 12px;\n  min-width: 0;\n  min-height: 0;\n  padding: 16px 14px 20px;\n  overflow-x: hidden;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  scrollbar-color: var(--rk-lime-muted) transparent;\n  -webkit-overflow-scrolling: touch;\n}\n#scr-lime .rk-lime-date {\n  align-self: center;\n  flex: none;\n  max-width: 100%;\n  margin: 2px 0 4px;\n  padding: 4px 11px;\n  border-radius: 20px;\n  background: var(--rk-lime-accent);\n  color: var(--rk-lime-on-accent);\n  font-size: 10px;\n  line-height: 1.5;\n  text-align: center;\n  overflow-wrap: anywhere;\n}\n#scr-lime .rk-lime-message { display: flex; flex: none; align-items: flex-start; gap: 8px; min-width: 0; width: 100%; }\n#scr-lime .rk-lime-message-content { display: flex; flex-direction: column; align-items: flex-start; min-width: 0; max-width: calc(100% - 48px); }\n#scr-lime .rk-lime-sender { margin: 0 0 4px 2px; color: var(--rk-lime-secondary); font-size: 11px; line-height: 1.4; overflow-wrap: anywhere; }\n#scr-lime .rk-lime-bubble {\n  position: relative;\n  min-width: 0;\n  max-width: 100%;\n  padding: 10px 13px;\n  border: 0;\n  border-radius: 16px;\n  background: var(--rk-lime-incoming);\n  color: var(--rk-lime-text);\n  box-shadow: none;\n  font-size: 14px;\n  line-height: 1.65;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  word-break: normal;\n}\n#scr-lime .rk-lime-message.in .rk-lime-bubble { border-top-left-radius: 5px; }\n#scr-lime .rk-lime-bubble::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: -5px;\n  width: 10px;\n  height: 12px;\n  background: inherit;\n  clip-path: polygon(0 0, 100% 0, 100% 100%);\n  pointer-events: none;\n}\n#scr-lime .rk-lime-message.out { justify-content: flex-end; padding-left: 32px; }\n#scr-lime .rk-lime-message.out .rk-lime-message-avatar,\n#scr-lime .rk-lime-message.out .rk-lime-sender { display: none; }\n#scr-lime .rk-lime-message.out .rk-lime-message-content { align-items: flex-end; max-width: 100%; }\n#scr-lime .rk-lime-message.out .rk-lime-bubble { background: var(--rk-lime-outgoing); color: var(--rk-lime-on-outgoing); border-top-right-radius: 5px; }\n#scr-lime .rk-lime-message.out .rk-lime-bubble::before { left: auto; right: -5px; clip-path: polygon(0 0, 100% 0, 0 100%); }\n#scr-lime .rk-lime-message-meta { margin: 4px 2px 0; color: var(--rk-lime-muted); font-size: 10px; line-height: 1.4; overflow-wrap: anywhere; }\n#scr-lime .rk-lime-turn-separator {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  gap: 8px;\n  margin: 8px 0 2px;\n  color: var(--rk-lime-muted);\n  font-size: 10px;\n  line-height: 1.6;\n  text-align: center;\n  overflow-wrap: anywhere;\n}\n#scr-lime .rk-lime-turn-separator::before,\n#scr-lime .rk-lime-turn-separator::after { content: \"\"; flex: 1; height: 1px; background: var(--rk-lime-line); }\n#scr-lime .rk-lime-empty { margin: auto; padding: 28px 22px; max-width: 360px; color: var(--rk-lime-secondary); font-size: 13px; line-height: 1.8; text-align: cent