\\": \\\"amane\\\",\\n          \\\"status\\\": \\\"bye\\\",\\n          \\\"label\\\": \\\"第二轮 · 对手食物中毒\\\",\\n          \\\"detail\\\": \\\"天音的未具名对手因食物中毒弃权，天音不战而胜。具体身份未明，不能绑定为D-1或D-2。\\\",\\n          \\\"evidence\\\": [\\n            \\\"第7卷 L6476\\\",\\n            \\\"第7卷 L6530–6532\\\"\\n          ],\\n          \\\"from\\\": [\\n            \\\"d-r1-1\\\",\\n            \\\"d-r1-2\\\"\\n          ]\\n        },\\n        {\\n          \\\"id\\\": \\\"d-r2-2\\\",\\n          \\\"round\\\": 2,\\n          \\\"slot\\\": 1,\\n          \\\"p1\\\": \\\"shizuku\\\",\\n          \\\"p2\\\": \\\"momiji\\\",\\n          \\\"winner\\\": \\\"shizuku\\\",\\n          \\\"status\\\": \\\"played\\\",\\n          \\\"label\\\": \\\"第二轮第2场\\\",\\n          \\\"detail\\\": \\\"珠雫击败浅木椛，取得D区决赛资格。\\\",\\n          \\\"evidence\\\": [\\n            \\\"第7卷 L193–243\\\"\\n          ],\\n          \\\"from\\\": [\\n            \\\"d-r1-3\\\",\\n            \\\"d-r1-4\\\"\\n          ]\\n        },\\n        {\\n          \\\"id\\\": \\\"d-r3-1\\\",\\n          \\\"round\\\": 3,\\n          \\\"slot\\\": 0,\\n          \\\"p1\\\": \\\"amane\\\",\\n          \\\"p2\\\": \\\"shizuku\\\",\\n          \\\"winner\\\": \\\"amane\\\",\\n          \\\"status\\\": \\\"bye\\\",\\n          \\\"label\\\": \\\"D区决赛未开打 · 天音晋级\\\",\\n          \\\"detail\\\": \\\"珠雫赛前袭击天音失败，双方没有正式入场交战。珠雫被判失格，天音晋级；准备室冲突不是有效的区决赛。\\\",\\n          \\\"evidence\\\": [\\n            \\\"第7卷 L6514–6598\\\",\\n            \\\"第8卷 L737–753\\\"\\n          ],\\n          \\\"from\\\": [\\n            \\\"d-r2-1\\\",\\n            \\\"d-r2-2\\\"\\n          ]\\n        }\\n      ]\\n    }\\n  ],\\n  \\\"finals\\\": [\\n    {\\n      \\\"id\\\": \\\"sf-1\\\",\\n      \\\"round\\\": 4,\\n      \\\"slot\\\": 0,\\n      \\\"p1\\\": \\\"ouma\\\",\\n      \\\"p2\\\": \\\"stella\\\",\\n      \\\"winner\\\": \\\"stella\\\",\\n      \\\"status\\\": \\\"played\\\",\\n      \\\"label\\\": \\\"准决赛第一场 · A区对B区\\\",\\n      \\\"detail\\\": \\\"史黛菈击败王马，取得决赛资格。\\\",\\n      \\\"evidence\\\": [\\n        \\\"第8卷 L3122–3126\\\"\\n      ],\\n      \\\"from\\\": [\\n        \\\"a-r3-1\\\",\\n        \\\"b-r3-1\\\"\\n      ]\\n    },\\n    {\\n      \\\"id\\\": \\\"sf-2\\\",\\n      \\\"round\\\": 4,\\n      \\\"slot\\\": 1,\\n      \\\"p1\\\": \\\"ikki\\\",\\n      \\\"p2\\\": \\\"amane\\\",\\n      \\\"winner\\\": \\\"ikki\\\",\\n      \\\"status\\\": \\\"played\\\",\\n      \\\"label\\\": \\\"准决赛第二场 · C区对D区\\\",\\n      \\\"detail\\\": \\\"一辉在正式比赛中获裁判判胜。天音此后失控追击属于赛后事件，不是另一场准决赛。\\\",\\n      \\\"evidence\\\": [\\n        \\\"第8卷 L4883–4889\\\"\\n      ],\\n      \\\"from\\\": [\\n        \\\"c-r3-1\\\",\\n        \\\"d-r3-1\\\"\\n      ]\\n    },\\n    {\\n      \\\"id\\\": \\\"final\\\",\\n      \\\"round\\\": 5,\\n      \\\"slot\\\": 0,\\n      \\\"p1\\\": \\\"stella\\\",\\n      \\\"p2\\\": \\\"ikki\\\",\\n      \\\"winner\\\": \\\"ikki\\\",\\n      \\\"status\\\": \\\"played\\\",\\n      \\\"label\\\": \\\"决赛 · 一辉夺冠\\\",\\n      \\\"detail\\\": \\\"一辉击败史黛菈，获得冠军，史黛菈为亚军。王马因天音严重犯规自动取得季军，原文没有另打一场季军战。\\\",\\n      \\\"evidence\\\": [\\n        \\\"第9卷 L5959–5973\\\",\\n        \\\"第9卷 L7430–7450\\\"\\n      ],\\n      \\\"from\\\": [\\n        \\\"sf-1\\\",\\n        \\\"sf-2\\\"\\n      ]\\n    }\\n  ],\\n  \\\"special\\\": {\\n    \\\"title\\\": \\\"B区首轮第4场 · 史黛菈1对4\\\",\\n    \\\"participants\\\": [\\n      \\\"stella\\\",\\n      \\\"mikoto\\\",\\n      \\\"hiraga\\\",\\n      \\\"rinna\\\",\\n      \\\"tatara\\\"\\n    ],\\n    \\\"winner\\\": \\\"stella\\\",\\n    \\\"detail\\\": \\\"原定史黛菈对鹤屋；已经各赢过首轮的平贺、风祭、多多良作为特别成员加入鹤屋一方。经有关选手同意、委员会许可，史黛菈须击败四人才获胜；鹤屋或任一特别成员击败史黛菈，均视为鹤屋获胜。史黛菈赢下特别战后，另经两人弃权、平贺失格而提前出线；并非一胜自动记作三轮胜利。\\\",\\n    \\\"evidence\\\": [\\n      \\\"第5卷 L8139–8141\\\",\\n      \\\"第5卷 L8219–8239\\\",\\n      \\\"第6卷 L2491–2501\\\",\\n      \\\"第6卷 L5028–5042\\\"\\n    ]\\n  }\\n};\\n\\n\\u003c/script>\\n\\u003cscript>\\nwindow.TOURNAMENT_PORTRAITS = {\\\"ikki\\\":\\\"https://eriribot.github.io/r