ikyo\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/kikyo.png\\\",\\\"HagureKikyō\\\":\\\"https://eriribot.github.io/rakudai-knight/resource/knightavatars/prepared/kikyo.png\\\"};\\n\\u003c/script>\\n\\u003cscript>\\nfunction read(input, providedView) {\\n  const snapshot = input?.state ? input : { state: input?.stat_data || input };\\n  const stat = structuredClone(snapshot.state?.stat_data || snapshot.state || {});\\n  const source = snapshot.source ? structuredClone(snapshot.source) : null;\\n  const pending = snapshot.pending === true;\\n  const view = providedView || deriveTournament(stat);\\n  const row = view.roster.find(person => person.id === view.playerId);\\n  const player = {\\n    id: view.playerId,\\n    name: row?.name || stat.玩家?.姓名 || '未建档',\\n    school: stat.玩家?.所属 || '所属待确认',\\n    device: stat.玩家?.固有灵装 || '灵装待登记',\\n    rank: stat.玩家?.登记等级 || '未登记',\\n  };\\n  let qualification;\\n  const status = (key, label, reason, representatives = []) => ({ status: key, label, reason, representatives });\\n  if (pending) {\\n    qualification = status('pending', '等待 MVU 保存', '当前回复尚未保存完成，暂不确认代表资格。');\\n  } else if (!view.applicable) {\\n    qualification = status('not-applicable', '他校资格待确认', '当前所属不适用破军选拔；保留角色档案，须依据所属学校的代表资格进入全国赛。');\\n  } else if (snapshot.incomplete === true || !view.exists || !view.complete || view.tournament?.状态 !== '已结束') {\\n    qualification = status('unconfirmed', '代表资格待确认', '当前选拔仍在进行或完整账本尚未确认，已记录积分和背景推演不直接授予代表资格。');\\n  } else if (view.qualificationTie) {\\n    qualification = status('tie', '代表席位同分待决', '第六名席位边界同分，须由本局附加赛或已确认规则决定。');\\n  } else if (!row) {\\n    qualification = status('unconfirmed', '玩家参赛身份待确认', '当前选拔名册尚未绑定本局玩家。');\\n  } else {\\n    const representatives = view.eligible.slice(0, view.tournament.代表名额);\\n    const qualified = representatives.some(person => person.id === player.id);\\n    qualification = status(qualified ? 'qualified' : 'not-qualified', qualified ? '已取得破军代表资格' : '本届未取得代表资格',\\n      qualified ? '已结束的完整选拔账本无席位同分，玩家位于有效代表名额内。' : '已结束的完整选拔账本无席位同分，玩家未列入有效代表名额。', representatives);\\n  }\\n  return { stat, source, pending, view, player, qualification };\\n}\\n\\nwindow.RK_PREVIEW_MVU = { read: input => read(input, input.view) };\\n\\u003c/script>\\n\\u003cscript>\\n(() => {\\n  const embedded = window.RK_TOURNAMENT_EMBEDDED === true;\\n  const model = window.RK_PREVIEW_MVU;\\n  const bracketModel = window.RK_PREVIEW_BRACKET;\\n  const $ = selector => document.querySelector(selector);\\n  const esc = value => String(value ?? '').replace(/[&\\u003c>\\\"']/g, c => ({ '&': '&amp;', '\\u003c': '&lt;', '>': '&gt;', '\\\"': '&quot;', \\\"'\\\": '&#39;' }[c]));\\n  const normalizeName = name => String(name).normalize('NFKC').replace(/[\\\\s·・･‧•．.]/g, '');\\n  const ui = { page: 'selection', sample: 'selection', region: 'A', match: null, bracket: null, display: {} };\\n  let current;\\n  const main = $('#session-main');\\n  const dialog = $('#session-dialog');\\n  const roundLabels = ['', '首轮 · 32 → 16', '第二轮 · 16 → 8', '分区决赛 · 8 → 4', '准决赛', '决赛'];\\n\\n  function portrait(name, isPlayer = false) {\\n    const catalog = window.TOURNAMENT_ROLE_PORTRAITS || {};\\n    const canonId = Object.keys(window.TOURNAMENT_DATA.players).find(id => normalizeName(window.TOURNAMENT_DATA.players[id].name) === normalizeName(name));\\n    const src = isPlayer && ui.display.avatarUrl || catalog[normalizeName(name)] || window.TOURNAMENT_PORTRAITS[canonId];\\n    const safe = src && /^(?:assets\\\\/|data:image\\\\/(?:png|jpeg|webp|gif);base64,|https:\\\\/\\\\/)/.test(src);\\n    return `\\u003cdiv class=\\\"fighter-avatar${isPlayer ? ' session-player-avatar' : ''}\\\">${safe ? `\\u003cimg src=\\\"${esc(src)}\\\" alt=\\\"\\\" loading=\\\"lazy\\\">` : `\\u003cspan class=\\\"portrait-fallback\\\" aria-hidden=\\\"true\\\">${esc(Array.from(name || '?')[0])}\\u003c/span>`}\\u003c/div>`;\\n  }\\n  function person(id) { return ui.bracket?.players[id]; }\\n  function displayName(id) { return person(id)?.name || '等待上轮胜者'; }\\n  function face(id) { return portrait(displayName(id), person(id)?.player); }\\n  function openDialog(content) { $('#session-dialog-content').innerHTML = content; dialog.showModal(); }\\n  function load(snapshot, display = {}) {\\n    current = model.read(snapshot);\\n    ui.display = display;\\n    if (!embedded || display.reset) {\\n      ui.bracket = null;\\n      ui.match = null;\\n      ui.page = 'selection';\\n      dialog.close();\\n    }\\n    render();\\n  }\\n  function loadSample(key) {\\n    ui.sample = key;\\n    $('#snapshot-sample').value = key;\\n    const sample = model.samples[key];\\n    load(sample.state);\\n    $('#snapshot-notice').textContent = sample.description;\\n  }\\n  // 正式终端传入当前显示快照及共享选拔视图；本页不再次读取酒馆变量。\\n  window.RK_MATCH_PREVIEW = { setSnapshot(snapshot, display = {}) {\\n    ui.sample = 'imported';\\n    $('#snapshot-sample').value = '';\\n    load(snapshot, display);\\n    $('#snapshot-notice').textContent = display.sourceLabel || '已读取传入的 MVU 快照；全国赛签位等待独立赛程记录。';\\n  } };\\n\\n  function renderProfile() {\\n    const p = current.player, q = current.qualification, v = current.view;\\n    const row = v.roster.find(item => item.id === v.playerId);\\n    $('#session-profile').innerHTML = `\\u003csection class=\\\"session-profile\\\">${portrait(p.name, true)}\\u003cdiv class=\\\"session-identity\\\">\\u003cspan class=\\\"screen-kicker\\\">${esc(current.stat.系统?.主角模式 || '现有角色档案')}\\u003c/span>\\u003ch1>${esc(p.name || '尚未建档')}\\u003c/h1>\\u003cp>${esc(p.school || '所属待填写')}　\\u003cspan>${esc(p.rank === '未登记' ? '等级未登记' : p.rank + '级')} / ${esc(p.device || '灵装待填写')}\\u003c/span>\\u003c/p>\\u003c/div>\\u003cdiv class=\\\"session-standing\\\">\\u003cb>${esc(q.label)}\\u003c/b>\\u003cspan>${row ? `${row.wins == null ? '战绩待补' : `${row.wins}胜 ${row.losses}负`} · ${row.points == null ? '总分待确认' : `${row.points}分`}` : '等待本局选拔记录'}\\u003c/span>\\u003c/div>\\u003c/section>`;\\n  }\\n  function card(row, representative = false) {\\n    return `\\u003cbutton type=\\\"button\\\" class=\\\"session-person ${row.player ? 'is-player' : ''}\\\" data-session-person=\\\"${esc(row.id)}\\\">${portrait(row.name, row.player)}\\u003cspan>\\u003cb>${esc(row.name)}\\u003c/b>\\u003csmall>${row.player ? '玩家 · 当前档案' : esc(row.source)}${representative ? ' · 代表' : ' · ' + esc(row.status)}\\u003c/small>\\u003c/span>\\u003cstrong>${row.points == null ? '待补' : row.points + '\\u003csmall>分\\u003c/small>'}\\u003c/strong>\\u003c/button>`;\\n  }\\n  function selectionMatch(match) {\\n    return `\\u003carticle class=\\\"session-ledger-row\\\">\\u003cspan>第${match.轮次}轮\\u003csmall>${esc(match.日期 || '日期待定')}\\u003c/small>\\u003c/span>\\u003cdiv>\\u003cb>${esc(match.甲方姓名)} \\u003cem>VS\\u003c/em> ${esc(match.乙方姓名)}\\u003c/b>\\u003csmall>${esc(match.地点 || '场地待定')}\\u003c/small>\\u003c/div>\\u003cstrong>${match.状态 === '已完成' ? esc(match.胜者 === match.甲方 ? match.甲方姓名 : match.乙方姓名) + ' 胜' : esc(match.状态)}\\u003c/strong>\\u003cp>${esc(match.依据)}\\u003c/p>\\u003c/article>`;\\n  }\\n  function renderSelection() {\\n    const v = current.view, q = current.qualification;\\n    const named = v.leaderboard.filter(row => row.source !== '原创' || row.player);\\n    const visible = [...named].sort((a, b) => Number(b.player) - Number(a.player));\\n    const others = v.leaderboard.filter(row => !named.includes(row));\\n    const real = v.matches.filter(match => !match.程序推演);\\n    const playerMatches = real.filter(match => [match.甲方, match.乙方].includes(v.playerId));\\n    main.innerHTML = `\\u003csection class=\\\"session-section\\\">\\u003cheader>\\u003cdiv>\\u003cspan class=\\\"screen-kicker\\\">SCHOOL QUALIFIERS\\u003c/span>\\u003ch2>${esc(v.tournament?.赛季 || '破军学园选拔赛')}\\u003c/h2>\\u003c/div>\\u003cspan class=\\\"session-status\\\">${esc(v.tournament?.状态 || '未建账本')}\\u003c/span>\\u003c/header>\\u003cdiv class=\\\"selection-summary\\\">\\u003cdiv class=\\\"selection-facts\\\">\\u003cdiv>\\u003cb>${v.tournament?.总轮次 || 20}\\u003c/b>\\u003cspan>轮校内积分赛\\u003c/span>\\u003c/div>\\u003cdiv>\\u003cb>${v.tournament?.代表名额 || 6}\\u003c/b>\\u003cspan>学园代表名额\\u003c/span>\\u003c/div>\\u003cdiv>\\u003cb>${v.roster.length}\\u003c/b>\\u003cspan>当前可见参赛者\\u003c/span>\\u003c/div>\\u003c/div>\\u003cdiv class=\\\"qualification-note\\\">\\u003cb>${esc(q.label)}\\u003c/b>\\u003cp>${esc(q.reason)}\\u003c/p>\\u003cbutton type=\\\"button\\\" data-session-page=\\\"national\\\">${q.status === 'qualified' ? '查看七星剑斗祭分区 →' : '查看七星剑斗祭准备情况 →'}\\u003c/button>\\u003c/div>\\u003c/div>${q.representatives.length ? `\\u003cdiv class=\\\"section-label\\\">本局代表名单\\u003c/div>\\u003cdiv class=\\\"session-roster\\\">${q.representatives.map(row => card(row, true)).join('')}\\u003c/div>` : ''}\\u003c/section>\\n      \\u003csection class=\\\"session-section\\\">\\u003cheader>\\u003cdiv>\\u003cspan class=\\\"screen-kicker\\\">ROSTER / 当前角色\\u003c/span>\\u003ch2>选拔参赛者\\u003c/h2>\\u003c/div>\\u003cspan class=\\\"subtle\\\">${esc(v.rankingLabel || '')}\\u003c/span>\\u003c/header>\\u003cdiv class=\\\"session-roster\\\">${visible.map(row => card(row)).join('') || '\\u003cp class=\\\"session-empty\\\">当前没有可显示的破军参赛名册。\\u003c/p>'}\\u003c/div>${others.length ? `\\u003cdetails class=\\\"session-details\\\">\\u003csummary>其他已登记参赛者 · ${others.length}人\\u003c/summary>\\u003cdiv class=\\\"session-roster\\\">${others.map(row => card(row)).join('')}\\u003c/div>\\u003c/details>` : ''}\\u003cp class=\\\"session-caption\\\">人物沿用当前名册；原作人物显示既有头像，自捏角色沿用开局头像，未设置时显示姓名首字。\\u003c/p>\\u003c/section>\\n      \\u003csection class=\\\"session-section\\\">\\u003cheader>\\u003cdiv>\\u003cspan class=\\\"screen-kicker\\\">MY MATCHES\\u003c/span>\\u003ch2>我的实际对局\\u003c/h2>\\u003c/div>\\u003cspan class=\\\"subtle\\\">${playerMatches.length}场记录\\u003c/span>\\u003c/header>${playerMatches.map(selectionMatch).join('') || '\\u003cp class=\\\"session-empty\\\">还没有保存玩家的实际对局。场外背景推演不会替你决定胜负。\\u003c/p>'}${real.length > playerMatches.length ? `\\u003cdetails class=\\\"session-details\\\">\\u003csummary>其他实际比赛 · ${real.length - playerMatches.length}场\\u003c/summary>${real.filter(match => !playerMatches.includes(match)).map(selectionMatch).join('')}\\u003c/details>` : ''}\\u003c/section>\\n      \\u003cdetails class=\\\"session-details source-details\\\">\\u003csummary>这份档案的数据来源与待补项\\u003c/summary>\\u003cp>玩家：玩家.姓名 / 所属 / 固有灵装；参赛者与对局：场景.选拔赛。头像使用终端显示配置，不写入 MVU。\\u003c/p>\\u003cp>${esc(current.source ? JSON.stringify(current.source) : '独立样本 / 无酒馆楼层连接')}\\u003c/p>${v.warnings.map(warning => `\\u003cp>${esc(warning)}\\u003c/p>`).join('')}\\u003c/details>`;\\n  }\\n  function emptyNational() {\\n    const q = current.qualification;\\n    return `\\u003cdiv class=\\\"national-gate\\\">\\u003cspan class=\\\"screen-kicker\\\">SEVEN STARS / DRAW PENDING\\u003c/span>\\u003ch2>${q.status === 'qualified' ? '代表资格已确认，等待七星剑斗祭抽签' : '七星剑斗祭 · 等待资格与分组'}\\u003c/h2>\\u003cp>${esc(q.reason)}\\u003c/p>\\u003cdiv class=\\\"empty-zones\\\">${[...'ABCD'].map(z => `\\u003cdiv>\\u003cb>${z}\\u003c/b>\\u003cspan>8 个席位\\u003c/span>\\u003csmall>对阵待公布\\u003c/small>\\u003c/div>`).join('')}\\u003c/div>\\u003cp class=\\\"session-caption\\\">现有 MVU 尚未保存全国赛签表。选拔名册保留在上一步，获得资格也不会直接生成本局对手。\\u003c/p>${!embedded && q.status === 'qualified' ? '\\u003cbutton type=\\\"button\\\" class=\\\"primary-action\\\" data-demo-draw>演示抽签后的界面 →\\u003c/button>\\u003csmall class=\\\"demo-disclaimer\\\">此按钮只生成预览签表，不代表本局已经抽签。\\u003c/small>' : '\\u003cbutton type=\\\"button\\\" data-session-page=\\\"selection\\\">返回选拔记录\\u003c/button>'}\\u003c/div>`;\\n  }\\n  function matchCard(match) {\\n    const winner = match.winner;\\n    return `\\u003cbutton type=\\\"button\\\" class=\\\"session-match ${winner ? 'completed' : ''} ${[match.p1, match.p2].some(id => person(id)?.player) ? 'my-match' : ''}\\\" data-session-match=\\\"${match.id}\\\" data-session-node=\\\"${match.id}\\\">\\u003csmall>${esc(roundLabels[match.round])}\\u003cspan>${winner ? '已演示赛果' : '待赛'}\\u003c/span>\\u003c/small>${[match.p1, match.p2].map(id => `\\u003cspan class=\\\"session-side ${id && id === winner ? 'won' : ''}\\\">${face(id)}\\u003cspan>\\u003cb>${esc(displayName(id))}\\u003c/b>\\u003csmall>${person(id)?.player ? '玩家 · 本局角色' : esc(person(id)?.school || '晋级后填入')}\\u003c/small>\\u003c/span>\\u003cem>${id && id === winner ? 'WIN' : ''}\\u003c/em>\\u003c/span>`).join('')}\\u003c/button>`;\\n  }\\n  function renderBracket() {\\n    const list = ui.bracket.matches.filter(m => m.zone === ui.region);\\n    const rounds = ui.region === 'finals' ? [4, 5] : [1, 2, 3];\\n    const last = list.at(-1);\\n    const qualifier = last.winner;\\n    return `\\u003cdiv class=\\\"session-bracket-scroll\\\">\\u003cdiv class=\\\"session-bracket ${ui.region === 'finals' ? 'session-finals' : ''}\\\">\\u003csvg class=\\\"session-connectors\\\" aria-hidden=\\\"true\\\">\\u003c/svg>${rounds.map(round => `\\u003csection class=\\\"session-round\\\">\\u003ch3>${roundLabels[round]}\\u003c/h3>\\u003cdiv class=\\\"session-round-matches\\\">${list.filter(m => m.round === round).map(matchCard).join('')}\\u003c/div>\\u003c/section>`).join('')}\\u003csection class=\\\"session-round\\\">\\u003ch3>${ui.region === 'finals' ? '七星剑王' : '全国四强'}\\u003c/h3>\\u003cdiv class=\\\"session-round-matches\\\">\\u003cdiv class=\\\"session-qualified\\\" data-session-node=\\\"qualified\\\">${face(qualifier)}\\u003cb>${esc(qualifier ? displayName(qualifier) : '席位待定')}\\u003c/b>\\u003cspan>${qualifier ? 'ADVANCE' : 'TO BE DECIDED'}\\u003c/span>\\u003c/div>\\u003c/div>\\u003c/section>\\u003c/div>\\u003c/div>`;\\n  }\\n  function tvContender(id) {\\n    return `\\u003cdiv class=\\\"tv-contender\\\">\\u003cdiv class=\\\"tv-portrait\\\">${face(id)}\\u003c/div>\\u003cb>${esc(displayName(id))}\\u003c/b>\\u003csmall>${esc(person(id)?.school || '等待晋级')}\\u003c/small>\\u003c/div>`;\\n  }\\n  function tvWing(id, label) { return `\\u003cdiv class=\\\"tv-wing\\\">\\u003cdiv class=\\\"tv-wing-inner\\\">${face(id)}\\u003cb>${esc(displayName(id))}\\u003c/b>\\u003csmall>${label}\\u003c/small>\\u003c/div>\\u003c/div>`; }\\n  function renderTV(match) {\\n    const mine = [match.p1, match.p2].some(id => person(id)?.player);\\n    const ready = !!(match.p1 && match.p2) && ![match.p1, match.p2].some(id => person(id).pending);\\n    const win = match.winner;\\n    const promotion = ['', '晋级全国16强', '晋级全国8强', '晋级全国4强', '晋级最终决赛', '第62届 · 七星剑王'][match.round];\\n    return `\\u003cdiv class=\\\"session-tv-head\\\">\\u003cbutton type=\\\"button\\\" data-session-back>← 分区晋级图\\u003c/button>\\u003cspan>${roundLabels[match.round]} / ${match.zone === 'finals' ? '全国' : match.zone + '区'} / ${mine ? '我的比赛' : '对局'}\\u003c/span>\\u003c/div>\\u003cdiv class=\\\"tv-stage\\\">\\u003cdiv class=\\\"tv-rig\\\">${tvWing(match.p1, 'RED CORNER')}\\u003cdiv class=\\\"tv-main\\\">\\u003cdiv class=\\\"tv-glass\\\">\\u003cdiv class=\\\"tv-topline\\\">${ready ? 'SEVEN STARS BATTLE' : 'WAITING FOR QUALIFIERS'}\\u003c/div>\\u003cdiv class=\\\"tv-center-content\\\">${win ? `\\u003cdiv class=\\\"tv-portrait winner-portrait\\\">${face(win)}\\u003c/div>` : `\\u003cdiv class=\\\"broadcast-duel\\\">${tvContender(match.p1)}\\u003cspan class=\\\"tv-vs\\\">VS\\u003c/span>${tvContender(match.p2)}\\u003c/div>`}\\u003c/div>\\u003cdiv class=\\\"tv-win ${win ? '' : 'advance'}\\\">${win ? 'WINNER' : 'VS'}\\u003c/div>\\u003cdiv class=\\\"tv-result-name\\\">${win ? esc(displayName(win)) : '胜者未定'}\\u003c/div>\\u003cdiv class=\\\"tv-promotion\\\">${win ? esc(promotion) : '等待本局行动与赛果'}\\u003c/div>\\u003c/div>\\u003c/div>${tvWing(match.p2, 'BLUE CORNER')}\\u003c/div>\\u003c/div>\\u003cdiv class=\\\"session-match-actions\\\">${mine && ready && !win ? `\\u003cbutton type=\\\"button\\\" class=\\\"primary-action\\\" data-prepare-action=\\\"${match.id}\\\">返回正文 · 准备我的行动\\u003c/button>\\u003cp>由你决定招式与行动；大屏在剧情确认赛果后才展示晋级。\\u003c/p>` : `\\u003cp>${win ? '预览赛果已带入下一轮。' : ready ? '对局已就绪，等待剧情记录。' : '上轮胜者尚未确定。'}\\u003c/p>`}${win ? '\\u003cbutton type=\\\"button\\\" data-session-back>查看更新后的签表 →\\u003c/button>' : ''}\\u003c/div>${ready ? `\\u003cdetails class=\\\"session-details demo-results\\\">\\u003csummary>预览用：演示赛果回填\\u003c/summary>\\u003cp>这些按钮只改变本页演示，不是正式判定，也不写入 MVU。\\u003c/p>\\u003cdiv>${[match.p1, match.p2].map(id => `\\u003cbutton type=\\\"button\\\" data-demo-winner=\\\"${esc(id)}\\\" data-demo-match=\\\"${match.id}\\\">${esc(displayName(id))} 胜出\\u003c/button>`).join('')}\\u003c/div>\\u003c/details>` : ''}`;\\n  }\\n  function renderNational() {\\n    if (!ui.bracket) { main.innerHTML = emptyNational(); return; }\\n    const selected = ui.bracket.matches.find(m => m.id === ui.match);\\n    main.innerHTML = `\\u003cdiv class=\\\"session-demo-banner\\\">\\u003cspan>抽签演示\\u003c/span>\\u003cp>使用本局选拔代表；其余席位借用原著名单展示。这里的分组与赛果均不写入存档。\\u003c/p>\\u003cbutton type=\\\"button\\\" data-my-match>定位我的比赛 ↗\\u003c/button>\\u003c/div>\\u003cnav class=\\\"region-nav session-region-nav\\\" aria-label=\\\"演示赛区\\\">${[...'ABCD', 'finals'].map(z => `\\u003cbutton type=\\\"button\\\" data-session-region=\\\"${z}\\\" class=\\\"${z === ui.region ? 'active' : ''}\\\" aria-pressed=\\\"${z === ui.region}\\\">${z === 'finals' ? '冠军之路' : z + ' 区'}\\u003cspan>${z === 'finals' ? 'FINAL STAGE' : '8 → 1'}\\u003c/span>\\u003c/button>`).join('')}\\u003c/nav>\\u003csection class=\\\"screen session-national-screen\\\">\\u003cdiv class=\\\"screen-header\\\">\\u003cdiv>\\u003cspan class=\\\"screen-kicker\\\">${selected ? 'MATCH SCREEN' : 'REGIONAL BRACKET'}\\u003c/span>\\u003ch2>${selected ? '对战大屏' : ui.region === 'finals' ? '冠军之路' : ui.region + '区 · 通往四强'}\\u003c/h2>\\u003c/div>\\u003cspan class=\\\"subtle\\\">${selected ? '随赛果播放' : '点击对局，打开大屏'}\\u003c/span>\\u003c/div>${selected ? renderTV(selected) : renderBracket()}\\u003c/section>\\u003cp class=\\\"session-caption\\\">B区一对四可在“原著回放”查看；本局需剧情另行确认特别赛与退赛、失格，不预排史黛菈必胜。\\u003c/p>`;\\n    requestAnimationFrame(drawLines);\\n  }\\n  function drawLines() {\\n    const root = main.querySelector('.session-bracket');\\n    if (!root) return;\\n    const svg = root.querySelector('svg'), bounds = root.getBoundingClientRect();\\n    if (!bounds.width) return;\\n    const nodes = new Map([...root.querySelectorAll('[data-session-node]')].map(el => [el.dataset.sessionNode, el]));\\n    const matches = ui.bracket.matches.filter(m => m.zone === ui.region);\\n    const edges = matches.flatMap(m => m.from.map(id => [id, m.id]));\\n    edges.push([matches.at(-1).id, 'qualified']);\\n    svg.setAttribute('viewBox', `0 0 ${bounds.width} ${bounds.height}`);\\n    svg.innerHTML = edges.filter(([a, b]) => nodes.has(a) && nodes.has(b)).map(([a, b]) => {\\n      const x = nodes.get(a).getBoundingClientRect(), y = nodes.get(b).getBoundingClientRect();\\n      const x1 = x.right - bounds.left, y1 = x.top + x.height / 2 - bounds.top, x2 = y.left - bounds.left, y2 = y.top + y.height / 2 - bounds.top;\\n      return `\\u003cpath class=\\\"${ui.bracket.matches.find(m => m.id === a).winner ? 'progressed' : ''}\\\" d=\\\"M${x1},${y1} H${(x1 + x2) / 2} V${y2} H${x2}\\\"/>`;\\n    }).join('');\\n  }\\n  function render() {\\n    renderProfile();\\n    document.querySelectorAll('[data-session-page]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.sessionPage === ui.page)));\\n    if (ui.page === 'selection') renderSelection(); else renderNational();\\n  }\\n  function openPerson(id) {\\n    const row = current.view.roster.find(row => row.id === id);\\n    const known = current.stat.人际?.[row.name]?.已知资料 || {};\\n    const profile = row.player ? current.stat.玩家 : known;\\n    openDialog(`\\u003cp class=\\\"dialog-kicker\\\">CURRENT ROSTER / 本局人物\\u003c/p>\\u003ch2 id=\\\"session-dialog-title\\\">${esc(row.name)}\\u003c/h2>\\u003cdiv class=\\\"session-person-detail\\\">${portrait(row.name, row.player)}\\u003cdiv>\\u003cp>${row.player ? '玩家 · ' + esc(current.stat.系统?.主角模式) : esc(row.source + ' · ' + row.status)}\\u003c/p>\\u003cp>${esc(profile.所属 || profile.身份 || '身份资料待补')}\\u003c/p>\\u003cp>灵装：${esc(profile.固有灵装 || profile.灵装 || '尚未记录')}\\u003c/p>\\u003cp>登记等级：${esc(profile.登记等级 || '尚未记录')}\\u003c/p>\\u003c/div>\\u003c/div>\\u003cp>${esc(row.player ? profile.角色简介 : profile.已知能力 || '人际档案中暂无更多已知资料。')}\\u003c/p>\\u003cp>${row.points == null ? '选拔战绩尚未完整。' : `${row.wins}胜 ${row.losses}负 · ${row.points}分`}\\u003c/p>\\u003cp class=\\\"session-caption\\\">身份对应当前名册 ID：${esc(row.id)}\\u003c/p>`);\\n  }\\n  function prepareAction(id) {\\n    const match = ui.bracket.matches.find(m => m.id === id);\\n    const opponent = [match.p1, match.p2].find(id => !person(id)?.player);\\n    openDialog(`\\u003cp class=\\\"dialog-kicker\\\">MY TURN / 正文行动草稿\\u003c/p>\\u003ch2 id=\\\"session-dialog-title\\\">${esc(current.player.name)} 对 ${esc(displayName(opponent))}\\u003c/h2>\\u003clabel class=\\\"action-label\\\" for=\\\"session-action-text\\\">准备怎样行动？\\u003c/label>\\u003ctextarea id=\\\"session-action-text\\\" rows=\\\"5\\\" placeholder=\\\"写下你的出招、试探或临场决定……\\\">\\u003c/textarea>\\u003cp class=\\\"session-caption\\\">此处是离线预览。复制后可带回正文；不代替你发送消息，也不预判胜负。\\u003c/p>\\u003cbutton type=\\\"button\\\" id=\\\"copy-session-action\\\">复制行动草稿\\u003c/button>\\u003cp id=\\\"session-copy-status\\\" role=\\\"status\\\">\\u003c/p>`);\\n  }\\n  document.addEventListener('click', async event => {\\n    const button = event.target.closest('button');\\n    if (!button) return;\\n    if (button.dataset.sourceMode) {\\n      const session = button.dataset.sourceMode === 'session';\\n      if (session) window.RK_MATCH_CANON.pause();\\n      $('#session-view').hidden = !session;\\n      $('#canon-view').hidden = session;\\n      document.querySelectorAll('[data-source-mode]').forEach(b => b.setAttribute('aria-pressed', String(b === button)));\\n      if (session) render();\\n    } else if (button.dataset.sessionPage) { ui.page = button.dataset.sessionPage; ui.match = null; render(); }\\n    else if (button.dataset.sessionPerson) openPerson(button.dataset.sessionPerson);\\n    else if (!embedded && button.hasAttribute('data-demo-draw')) {\\n      ui.bracket = bracketModel.create(window.TOURNAMENT_DATA, current.qualification.representatives);\\n      const mine = ui.bracket.matches.find(m => [m.p1, m.p2].some(id => person(id)?.player));\\n      ui.region = mine?.zone || 'A'; ui.match = null; render();\\n    } else if (button.dataset.sessionRegion) { ui.region = button.dataset.sessionRegion; ui.match = null; render(); }\\n    else if (button.dataset.sessionMatch) { ui.match = button.dataset.sessionMatch; render(); }\\n    else if (button.hasAttribute('data-session-back')) { ui.match = null; render(); }\\n    else if (button.hasAttribute('data-my-match')) {\\n      const mine = ui.bracket.matches.filter(m => [m.p1, m.p2].some(id => person(id)?.player));\\n      const match = mine.find(m => !m.winner) || mine.at(-1);\\n      if (match) { ui.region = match.zone; ui.match = match.id; render(); }\\n    } else if (!embedded && button.dataset.demoWinner) { bracketModel.settle(ui.bracket, button.dataset.demoMatch, button.dataset.demoWinner); render(); }\\n    else if (button.dataset.prepareAction) prepareAction(button.dataset.prepareAction);\\n    else if (button.hasAttribute('data-session-close')) dialog.close();\\n    else if (button.id === 'copy-session-action') {\\n      const input = $('#session-action-text');\\n      try { await navigator.clipboard.writeText(input.value); $('#session-copy-status').textContent = '已复制，可以带回正文继续行动。'; }\\n      catch { input.select(); $('#session-copy-status').textContent = '请复制当前选中的行动文字。'; }\\n    }\\n  });\\n  if (!embedded) {\\n  $('#snapshot-sample').innerHTML = Object.entries(model.samples).map(([key, sample]) => `\\u003coption value=\\\"${key}\\\">${esc(sample.label)}\\u003c/option>`).join('');\\n  $('#snapshot-sample').addEventListener('change', event => loadSample(event.target.value));\\n  $('#import-snapshot').addEventListener('click', () => $('#snapshot-file').click());\\n  $('#snapshot-file').addEventListener('change', async event => {\\n    const file = event.target.files[0];\\n    if (!file) return;\\n    try {\\n      const json = JSON.parse(await file.text());\\n      window.RK_MATCH_PREVIEW.setSnapshot(json);\\n      $('#snapshot-notice').textContent = `${file.name} · 本地读取，不上传；签位等待全国赛记录。`;\\n    } catch (error) { $('#snapshot-notice').textContent = '这份文件未能读取为 MVU 快照：' + error.message; }\\n    event.target.value = '';\\n  });\\n  loadSample('selection');\\n  } else {\\n    const tools = $('.snapshot-tools');\\n    tools.querySelector('label').hidden = true;\\n    $('#import-snapshot').hidden = true;\\n    const manage = document.createElement('button');\\n    manage.type = 'button';\\n    manage.textContent = '登记与维护选拔记录';\\n    manage.addEventListener('click', () => window.RK_TERMINAL_ACTIONS.editSelection());\\n    tools.prepend(manage);\\n    main.innerHTML = '\\u003cp class=\\\"session-caption\\\">正在读取本局已保存档案……\\u003c/p>';\\n  }\\n  new ResizeObserver(drawLines).observe(main);\\n})();\\n\\n\\u003c/script>\\n\\u003cscript>\\n(() => {\\n  const data = window.TOURNAMENT_DATA;\\n  const portraits = window.TOURNAMENT_PORTRAITS;\\n  const allMatches = [...data.regions.flatMap(region => region.matches), ...data.finals];\\n  const matchesById = new Map(allMatches.map(match => [match.id, match]));\\n  const stages = ['开幕列阵', '16强争夺', '8强争夺', '4强争夺', '准决赛', '冠军诞生'];\\n  const roundNames = ['', '16强争夺 · 32→16', '8强争夺 · 16→8', '4强争夺 · 8→4', '准决赛 · 4→2', '决赛 · 2→1'];\\n  const state = { view: 'B', stage: 0, display: 'tree', focus: 'b-r1-4', timer: null };\\n  const $ = selector => document.querySelector(selector);\\n  const board = $('#board');\\n  const dialog = $('#match-dialog');\\n  const esc = value => String(value).replace(/[&\\u003c>\\\"']/g, char => ({ '&': '&amp;', '\\u003c': '&lt;', '>': '&gt;', '\\\"': '&quot;', \\\"'\\\": '&#39;' }[char]));\\n  const player = id => data.players[id];\\n  const name = id => player(id)?.name || '未具名选手';\\n  const effectiveRound = match => match.id === 'b-r3-1' ? 2 : match.round;\\n  const resolved = match => state.stage >= effectiveRound(match);\\n  const isWin = match => match.status === 'played' || match.status === 'special';\\n  const shortNames = { stella: '史黛菈', mikoto: '鹤屋美琴', hiraga: '平贺玲泉', rinna: '风祭凛奈', tatara: '多多良幽衣' };\\n\\n  function avatar(id) {\\n    return `\\u003cdiv class=\\\"fighter-avatar\\\">${portraits[id]\\n      ? `\\u003cimg src=\\\"${portraits[id]}\\\" alt=\\\"\\\" loading=\\\"lazy\\\">`\\n      : `\\u003cspan class=\\\"portrait-fallback\\\" aria-hidden=\\\"true\\\">${id && !player(id).unnamed ? esc(name(id).slice(0, 1)) : '?'}\\u003c/span>`}\\u003c/div>`;\\n  }\\n\\n  function fighter(id, match, available) {\\n    const done = resolved(match);\\n    const won = available && done && id && match.winner === id;\\n    const lost = available && done && match.winner && id !== match.winner && isWin(match);\\n    let status = won ? (isWin(match) ? 'WIN' : 'ADV') : lost ? 'OUT' : '—';\\n    if (available && done && match.status === 'cancelled' && !won) status = '取消';\\n    if (available && done && match.status === 'bye' && !won) status = match.id === 'd-r3-1' ? '失格' : '缺席';\\n    const label = !available ? '上轮胜者待定' : id ? name(id) : match.id === 'b-r3-1' ? '无有效对手' : '未具名晋级者';\\n    const school = !available ? '等待晋级结果' : id ? player(id).school : match.id === 'b-r3-1' ? '赛事委员会确认出线' : '原著未交代身份';\\n    const className = won ? (isWin(match) ? 'won' : 'advanced') : lost ? 'lost' : !id || player(id).unnamed ? 'unknown' : '';\\n    return `\\u003cdiv class=\\\"fighter ${className}\\\">${avatar(available ? id : null)}\\u003cdiv class=\\\"fighter-name\\\">\\u003cb>${esc(label)}\\u003c/b>\\u003csmall>${esc(school)}\\u003c/small>\\u003c/div>\\u003cspan class=\\\"fighter-status\\\">${status}\\u003c/span>\\u003c/div>`;\\n  }\\n\\n  function matchCard(match) {\\n    const done = resolved(match);\\n    const available = match.round === 1 || state.stage >= match.round - 1;\\n    const roundLabel = roundNames[match.round];\\n    const topLabel = match.status === 'special' ? '首轮补赛 · 1 对 4' : roundLabel;\\n    const resultLabels = { played: '赛果已确认', bye: '不战晋级', cancelled: '比赛取消', unknown: '赛况未详', special: '特别赛胜出' };\\n    const status = done ? resultLabels[match.status] : '等待赛果';\\n    const footer = match.status === 'special' ? '特别成员：平贺 / 风祭 / 多多良' : '';\\n    return `\\u003cdiv class=\\\"match-wrap\\\">\\u003cbutton type=\\\"button\\\" class=\\\"match ${done ? match.status : 'pending'}\\\" data-match=\\\"${match.id}\\\" data-node=\\\"${match.id}\\\" aria-label=\\\"${esc(roundLabel + '：' + (available ? name(match.p1) + ' 对 ' + name(match.p2) : '等待上轮胜者') + '，' + status)}\\\">\\u003cdiv class=\\\"match-top\\\">\\u003cspan>${topLabel}\\u003c/span>\\u003cstrong class=\\\"${match.status === 'special' ? 'special-tag' : ''}\\\">${status}\\u003c/strong>\\u003c/div>${fighter(match.p1, match, available)}${fighter(match.p2, match, available)}${footer ? `\\u003cdiv class=\\\"match-result\\\">${footer}\\u003c/div>` : ''}\\u003c/button>\\u003c/div>`;\\n  }\\n\\n  function qualifier(id, source, champion = false) {\\n    const ready = resolved(source);\\n    return `\\u003cdiv class=\\\"match-wrap\\\">\\u003cdiv class=\\\"qualifier ${champion ? 'champion' : ''} ${ready ? '' : 'pending'}\\\" data-node=\\\"${id}\\\">\\u003cdiv class=\\\"qualifier-title\\\">${champion ? 'SEVEN STARS KING' : 'FINAL FOUR'}\\u003c/div>${avatar(ready ? source.winner : null)}\\u003ch3>${ready ? esc(name(source.winner)) : '席位待定'}\\u003c/h3>\\u003cp>${ready ? esc(player(source.winner).school) : '胜者将出现在这里'}\\u003c/p>\\u003cspan class=\\\"qualified-stamp\\\">${ready ? champion ? 'CHAMPION' : 'QUALIFIED' : 'TO BE DECIDED'}\\u003c/span>\\u003c/div>\\u003c/div>`;\\n  }\\n\\n  function column(title, english, className, content) {\\n    return `\\u003cdiv class=\\\"bracket-column\\\">\\u003cdiv class=\\\"round-title\\\">${title}\\u003cspan>${english}\\u003c/span>\\u003c/div>\\u003cdiv class=\\\"round-matches ${className}\\\">${content}\\u003c/div>\\u003c/div>`;\\n  }\\n\\n  function renderRegion(region) {\\n    $('#board-kicker').textContent = `BLOCK ${region.id} / EIGHT TO ONE`;\\n    $('#board-title').textContent = `${region.id} 区 · 通往四强`;\\n    $('#board-note').textContent = region.note;\\n    const lastMatch = region.matches.find(match => match.round === 3);\\n    board.innerHTML = `\\u003cdiv class=\\\"bracket-scroll\\\">\\u003cdiv class=\\\"bracket\\\">\\u003csvg class=\\\"connector-layer\\\" aria-hidden=\\\"true\\\">\\u003c/svg>${[1, 2, 3].map(round => column(['首轮 · 全国32→16', '第二轮 · 全国16→8', '分区决赛 · 全国8→4'][round - 1], `ROUND 0${round}`, `round-${round}`, region.matches.filter(match => match.round === round).map(matchCard).join(''))).join('')}${column('全国四强', 'QUALIFIED', 'round-winner', qualifier(`qualifier-${region.id}`, lastMatch))}\\u003c/div>\\u003c/div>`;\\n  }\\n\\n  function focusForStage() {\\n    if (state.view === 'all') return;\\n    if (state.view === 'finals') {\\n      state.focus = state.stage >= 5 ? 'final' : 'sf-2';\\n      return;\\n    }\\n    if (state.view === 'B') {\\n      state.focus = state.stage \\u003c= 1 ? 'b-r1-4' : 'b-r3-1';\\n      return;\\n    }\\n    const round = Math.max(1, Math.min(3, state.stage));\\n    const choices = data.regions.find(region => region.id === state.view).matches.filter(match => match.round === round);\\n    state.focus = (state.view === 'C' || (state.view === 'D' && round === 2) ? choices.at(-1) : choices[0]).id;\\n  }\\n\\n  function contender(id, className = '') {\\n    return `\\u003cdiv class=\\\"tv-contender ${className}\\\">\\u003cdiv class=\\\"tv-portrait\\\">${avatar(id)}\\u003c/div>\\u003cb>${esc(shortNames[id] || name(id))}\\u003c/b>\\u003csmall>${id ? esc(player(id).school) : '身份未记载'}\\u003c/small>\\u003c/div>`;\\n  }\\n\\n  function wing(id, label, winner = false) {\\n    return `\\u003cdiv class=\\\"tv-wing ${winner ? 'winner' : ''}\\\">\\u003cdiv class=\\\"tv-wing-inner\\\">${id ? avatar(id) : '\\u003cdiv class=\\\"league-seal\\\">Ⅶ\\u003c/div>'}\\u003cb>${esc(id ? shortNames[id] || name(id) : 'SEVEN STARS')}\\u003c/b>\\u003csmall>${esc(label)}\\u003c/small>\\u003c/div>\\u003c/div>`;\\n  }\\n\\n  function promotion(match) {\\n    if (match.id === 'b-r1-4') return '一人击败四人 · 正式首轮胜出';\\n    if (match.id === 'b-r3-1') return '两人弃权、一人失格 · 委员会确认晋级四强';\\n    if (!match.winner) return match.status === 'cancelled' ? '本场没有举行' : '原著未交代本场胜者';\\n    return ['', '晋级全国16强', '晋级全国8强', '晋级全国4强', '晋级最终决赛', '第62届 · 七星剑王'][match.round];\\n  }\\n\\n  function matchNote(match) {\\n    if (match.id === 'b-r1-4') return '时序：一辉对诸星结束 → 补办B区第4场（一对四）→ 整理场地后开始D区。此战仍属首轮。';\\n    if (match.id === 'c-r1-4') return '本场为“第一轮，C区第四场”。一辉胜出并进军第二轮；诸星首轮止步。这里的16强是胜者晋级目标。';\\n    if (match.id === 'b-r3-1') return '先有一对四的实战胜利，后有多多良与风祭弃权、平贺失格；B区第二、三轮取消，史黛菈提前晋级四强。';\\n    return match.detail;\\n  }\\n\\n  function renderBroadcast() {\\n    const match = matchesById.get(state.focus);\\n    const done = resolved(match);\\n    const special = match.status === 'special';\\n    const available = match.round === 1 || state.stage >= match.round - 1;\\n    const confirmedWinner = done && match.winner;\\n    const liveWin = confirmedWinner && isWin(match);\\n    const title = special ? '史黛菈 · 惊天一对四' : match.id === 'c-r1-4' ? '一辉 VS 诸星 · 16强争夺' : match.id === 'b-r3-1' ? 'B区出线 · 委员会判定' : match.round === 5 ? '决赛 · 七星剑王之争' : `${state.view === 'finals' ? '全国' : state.view + '区'} · ${roundNames[match.round]}`;\\n    $('#board-kicker').textContent = special ? 'B区第四场 / 接续C区赛事的首轮补赛' : `第${match.round}轮 / ${roundNames[match.round]}`;\\n    $('#board-title').textContent = title;\\n    $('#board-note').textContent = matchNote(match);\\n    const result = liveWin ? 'WINNER' : confirmedWinner ? 'ADVANCE' : done ? match.status === 'cancelled' ? 'CANCELLED' : 'UNRECORDED' : 'VS';\\n    const center = special\\n      ? `\\u003cdiv class=\\\"tv-special-duel ${done ? 'resolved' : ''}\\\">${contender('stella', 'main-contender ' + (done ? 'winner' : ''))}\\u003cspan class=\\\"tv-vs\\\">VS\\u003c/span>\\u003cdiv class=\\\"tv-opponents\\\">${['mikoto', 'hiraga', 'rinna', 'tatara'].map(id => contender(id)).join('')}\\u003c/div>\\u003c/div>`\\n      : confirmedWinner\\n        ? `\\u003cdiv class=\\\"tv-portrait winner-portrait\\\">${avatar(match.winner)}\\u003c/div>`\\n        : `\\u003cdiv class=\\\"broadcast-duel\\\">${contender(available ? match.p1 : null)}\\u003cspan class=\\\"tv-vs\\\">VS\\u003c/span>${contender(available ? match.p2 : null)}\\u003c/div>`;\\n    const left = special ? wing(null, '第62届 · 七星剑斗祭') : wing(available ? match.p1 : null, available && done && match.p1 === match.winner ? 'WIN' : 'RED CORNER', liveWin && match.p1 === match.winner);\\n    const right = special ? wing(null, 'SPECIAL BATTLE · 1 VS 4') : wing(available ? match.p2 : null, available && done && match.p2 === match.winner ? 'WIN' : 'BLUE CORNER', liveWin && match.p2 === match.winner);\\n    const strip = done ? `${confirmedWinner ? name(match.winner) + ' · ' : ''}${promotion(match)}` : `${roundNames[match.round]} · 等待开赛与判定`;\\n    const matches = state.view === 'finals' ? data.finals : data.regions.find(region => region.id === state.view).matches;\\n    board.innerHTML = `\\u003cdiv class=\\\"tv-stage\\\">\\u003cdiv class=\\\"tv-rig\\\">${left}\\u003cdiv class=\\\"tv-main ${special ? 'special' : ''}\\\">\\u003cdiv class=\\\"tv-glass\\\">\\u003cdiv class=\\\"tv-topline\\\">${special ? 'SPECIAL BATTLE · 1 VS 4' : esc(roundNames[match.round])}\\u003c/div>\\u003cdiv class=\\\"tv-center-content\\\">${center}\\u003c/div>\\u003cdiv class=\\\"tv-win ${liveWin ? '' : 'advance'}\\\">${result}\\u003c/div>\\u003cdiv class=\\\"tv-result-name\\\">${confirmedWinner ? esc(name(match.winner)) : done ? '比赛记录' : '胜者未定'}\\u003c/div>\\u003cdiv class=\\\"tv-promotion\\\">${done ? esc(promotion(match)) : '只显示当前阶段已知结果'}\\u003c/div>\\u003c/div>\\u003c/div>${right}\\u003c/div>\\u003cdiv class=\\\"tv-result-strip\\\">${esc(strip)}\\u003c/div>\\u003c/div>\\u003cdiv class=\\\"battle-strip\\\" aria-label=\\\"选择本区对局\\\">${matches.map(item => `\\u003cbutton type=\\\"button\\\" class=\\\"battle-choice ${item.id === match.id ? 'active' : ''}\\\" data-focus=\\\"${item.id}\\\" aria-pressed=\\\"${item.id === match.id}\\\">\\u003csmall>${item.status === 'special' ? '首轮补赛 · 一对四' : item.status === 'cancelled' ? '取消 / 资格判定' : roundNames[item.round]}\\u003c/small>\\u003cb>${esc(item.status === 'special' ? '史黛菈 VS 四名对手' : item.id === 'b-r3-1' ? '史黛菈 · 提前出线' : name(item.p1) + ' / ' + name(item.p2))}\\u003c/b>\\u003c/button>`).join('')}\\u003c/div>`;\\n  }\\n\\n  function renderFinals() {\\n    $('#board-kicker').textContent = 'FINAL STAGE / THE LAST FOUR';\\n    $('#board-title').textContent = '冠军之路 · 最后的王座';\\n    $('#board-note').textContent = '准决赛配对：A区对B区、C区对D区。决赛由两场准决赛的胜者交锋。';\\n    const final = data.finals.find(match => match.round === 5);\\n    board.innerHTML = `\\u003cdiv class=\\\"bracket-scroll\\\">\\u003cdiv class=\\\"bracket final-board\\\">\\u003csvg class=\\\"connector-layer\\\" aria-hidden=\\\"true\\\">\\u003c/svg>${column('准决赛 · 四强', 'SEMIFINALS', 'round-2', data.finals.filter(match => match.round === 4).map(matchCard).join(''))}${column('最终决赛', 'GRAND FINAL', 'round-3', matchCard(final))}${column('七星剑王', 'CHAMPION', 'round-winner', qualifier('champion', final, true))}\\u003c/div>\\u003c/div>\\u003cdiv class=\\\"podium-note\\\">${state.stage >= 5 ? '\\u003cb>最终名次\\u003c/b>冠军：黑铁一辉　/　亚军：史黛菈　/　季军：黑铁王马。天音因犯规被剥夺资格，王马自动取得季军，没有另打一场季军赛。' : '\\u003cb>晋级路线\\u003c/b>A区胜者 × B区胜者，C区胜者 × D区胜者；两场准决赛的胜者晋级决赛。'}\\u003c/div>`;\\n  }\\n\\n  function rosterStatus(id, region) {\\n    if (state.stage === 0) return { label: '参赛', className: '' };\\n    if (state.stage >= 5 && ['ikki', 'stella', 'ouma', 'amane'].includes(id)) return { label: { ikki: '冠军', stella: '亚军', ouma: '季军', amane: '失格' }[id], className: id === 'amane' ? 'eliminated' : 'qualifying' };\\n    if (state.stage >= 2 && ['hiraga', 'rinna', 'tatara'].includes(id)) return { label: id === 'hiraga' ? '失格' : '弃权', className: 'eliminated' };\\n    const known = allMatches.filter(match => resolved(match) && [match.p1, match.p2].includes(id));\\n    const last = known.at(-1);\\n    if (!last || (!last.winner && last.status === 'unknown')) return { label: '未详', className: '' };\\n    if (last.winner && last.winner !== id) return { label: id === 'shizuku' && last.status === 'bye' ? '失格' : last.round === 1 ? '首轮止步' : '止步', className: 'eliminated' };\\n    if (id === 'stella' && state.stage === 4) return { label: '决赛', className: 'qualifying' };\\n    if (last.round === 4) return { label: '决赛', className: 'qualifying' };\\n    const regionalFinal = region.matches.find(match => match.round === 3);\\n    if (resolved(regionalFinal) && regionalFinal.winner === id) return { label: '四强', className: 'qualifying' };\\n    if (last.winner === id) return { label: last.round === 1 ? '晋级16强' : last.round === 2 ? '晋级8强' : '晋级', className: 'qualifying' };\\n    return { label: '未详', className: '' };\\n  }\\n\\n  function renderRoster() {\\n    $('#board-kicker').textContent = 'TOURNAMENT ROSTER / ALL 32 ENTRIES';\\n    $('#board-title').textContent = '正赛32人 · 参赛名单';\\n    $('#board-note').textContent = '18名已具名选手 + 14个未具名席位。驹城与新留仅给出姓氏；编号是展示占位，不是官方种子号。';\\n    board.innerHTML = `\\u003cdiv class=\\\"roster-grid\\\">${data.regions.map(region => `\\u003csection class=\\\"roster-zone\\\">\\u003cdiv class=\\\"roster-zone-head\\\">BLOCK ${region.id} · ${region.id} 区\\u003cbutton type=\\\"button\\\" data-open-region=\\\"${region.id}\\\">查看对阵 ↗\\u003c/button>\\u003c/div>${region.matches.filter(match => match.round === 1).flatMap(match => [match.p1, match.p2]).map((id, index) => {\\n      const status = rosterStatus(id, region);\\n      return `\\u003cbutton type=\\\"button\\\" class=\\\"roster-entry ${status.className} ${player(id).unnamed ? 'unknown' : ''}\\\" data-player=\\\"${id}\\\">\\u003cspan class=\\\"roster-index\\\">${String(index + 1).padStart(2, '0')}\\u003c/span>${avatar(id)}\\u003cspan class=\\\"fighter-name\\\">\\u003cb>${esc(name(id))}\\u003c/b>\\u003csmall>${esc(player(id).school)}\\u003c/small>\\u003c/span>\\u003cspan class=\\\"roster-flag\\\">${status.label}\\u003c/span>\\u003c/button>`;\\n    }).join('')}\\u003c/section>`).join('')}\\u003c/div>\\u003cdiv class=\\\"overview-finals\\\">${data.regions.map(region => {\\n      const match = region.matches.find(match => match.round === 3);\\n      return `\\u003cdiv class=\\\"overview-final-chip\\\">\\u003csmall>${region.id} 区出线\\u003c/small>\\u003cstrong>${resolved(match) ? esc(name(match.winner)) : '待定'}\\u003c/strong>\\u003c/div>`;\\n    }).join('')}\\u003c/div>`;\\n  }\\n\\n  function specialPerson(id) {\\n    return `\\u003cdiv class=\\\"special-person ${id === 'stella' && state.stage >= 1 ? 'winner' : ''}\\\">${avatar(id)}\\u003cspan>${esc(shortNames[id])}\\u003c/span>\\u003c/div>`;\\n  }\\n\\n  function renderSpecial() {\\n    const panel = $('#special-panel');\\n    panel.hidden = true;\\n    panel.innerHTML = '';\\n  }\\n\\n  function render() {\\n    document.querySelectorAll('[data-view]').forEach(button => {\\n      button.classList.toggle('active', button.dataset.view === state.view);\\n      button.setAttribute('aria-pressed', String(button.dataset.view === state.view));\\n    });\\n    document.querySelectorAll('[data-display]').forEach(button => {\\n      button.classList.toggle('active', button.dataset.display === state.display);\\n      button.setAttribute('aria-pressed', String(button.dataset.display === state.display));\\n    });\\n    $('.display-toggle').hidden = state.view === 'all';\\n    $('#match-source').hidden = state.view === 'all' || state.display === 'tree';\\n    $('#stages').innerHTML = stages.map((label, index) => `\\u003cbutton type=\\\"button\\\" data-stage=\\\"${index}\\\" class=\\\"${index \\u003c state.stage ? 'done' : index === state.stage ? 'current' : ''}\\\" aria-pressed=\\\"${index === state.stage}\\\">${label}\\u003c/button>`).join('');\\n    $('#stage-label').textContent = `0${state.stage} / ${stages[state.stage]}`;\\n    $('#previous').disabled = state.stage === 0;\\n    $('#next').disabled = state.stage === stages.length - 1;\\n    $('#play').textContent = state.timer ? 'Ⅱ 暂停播放' : '▶ 播放晋级';\\n    if (state.view === 'all') renderRoster();\\n    else if (state.display === 'broadcast') renderBroadcast();\\n    else if (state.view === 'finals') renderFinals();\\n    else renderRegion(data.regions.find(region => region.id === state.view));\\n    renderSpecial();\\n    requestAnimationFrame(drawConnectors);\\n  }\\n\\n  function drawConnectors() {\\n    const bracket = board.querySelector('.bracket');\\n    if (!bracket) return;\\n    const svg = bracket.querySelector('svg');\\n    const bounds = bracket.getBoundingClientRect();\\n    const nodes = new Map([...bracket.querySelectorAll('[data-node]')].map(node => [node.dataset.node, node]));\\n    const edges = [];\\n    for (const [id] of nodes) {\\n      const match = matchesById.get(id);\\n      if (match) match.from.forEach(source => edges.push([source, id]));\\n      else if (id === 'champion') edges.push(['final', id]);\\n      else if (id.startsWith('qualifier-')) edges.push([`${id.at(-1).toLowerCase()}-r3-1`, id]);\\n    }\\n    svg.setAttribute('viewBox', `0 0 ${bounds.width} ${bounds.height}`);\\n    svg.innerHTML = edges.filter(([source, target]) => nodes.has(source) && nodes.has(target)).map(([source, target]) => {\\n      const a = nodes.get(source).getBoundingClientRect();\\n      const b = nodes.get(target).getBoundingClientRect();\\n      const x1 = a.right - bounds.left, y1 = a.top + a.height / 2 - bounds.top;\\n      const x2 = b.left - bounds.left, y2 = b.top + b.height / 2 - bounds.top;\\n      const midpoint = (x1 + x2) / 2;\\n      const match = matchesById.get(source);\\n      const active = resolved(match);\\n      return `\\u003cpath class=\\\"connector ${active && match.winner ? 'progressed' : ''} ${active && match.status === 'cancelled' ? 'cancelled' : ''}\\\" d=\\\"M ${x1} ${y1} H ${midpoint} V ${y2} H ${x2}\\\"/>`;\\n    }).join('');\\n  }\\n\\n  function evidence(refs) {\\n    return `\\u003cdetails class=\\\"dialog-evidence\\\">\\u003csummary>展开原文依据\\u003c/summary>\\u003cp>${refs.map(esc).join('\\u003cbr>')}\\u003c/p>\\u003cp>行号对应「世界观 / 七星剑武祭考据」中记录的本地小说文本版本。完整论证见页面底部的考据文件。\\u003c/p>\\u003c/details>`;\\n  }\\n\\n  function showDialog(content) {\\n    $('#dialog-content').innerHTML = content;\\n    dialog.showModal();\\n  }\\n\\n  function person(id, vacant = false) {\\n    return `\\u003cdiv class=\\\"dialog-person\\\">${avatar(id)}\\u003cb>${vacant ? '无有效对手' : esc(name(id))}\\u003c/b>\\u003csmall>${vacant ? '比赛取消' : id ? esc(player(id).school) : '原著未记载身份'}\\u003c/small>\\u003c/div>`;\\n  }\\n\\n  function openMatch(id) {\\n    const match = matchesById.get(id);\\n    if (match.status === 'special') return openSpecial();\\n    const result = match.winner ? `${name(match.winner)} · ${isWin(match) ? 'WIN' : 'ADV 晋级'}` : match.status === 'cancelled' ? '比赛取消 · 无实战赛果' : '胜者未详';\\n    showDialog(`\\u003cp class=\\\"dialog-kicker\\\">MATCH ARCHIVE / 原著对局档案\\u003c/p>\\u003ch2 id=\\\"dialog-title\\\" class=\\\"dialog-title\\\">${esc(match.label)}\\u003c/h2>\\u003cdiv class=\\\"dialog-duel\\\">${person(match.p1, match.id === 'b-r3-1')}\\u003cspan class=\\\"dialog-vs\\\">VS\\u003c/span>${person(match.p2)}\\u003c/div>\\u003cdiv class=\\\"dialog-result\\\">${esc(result)}\\u003c/div>\\u003cp class=\\\"dialog-description\\\">${esc(match.detail)}\\u003c/p>${evidence(match.evidence)}`);\\n  }\\n\\n  function openSpecial() {\\n    showDialog(`\\u003cp class=\\\"dialog-kicker\\\">SPECIAL MATCH / 原著对局档案\\u003c/p>\\u003ch2 id=\\\"dialog-title\\\" class=\\\"dialog-title\\\">史黛菈 · 一对四特别赛\\u003c/h2>\\u003cdiv class=\\\"dialog-special-grid\\\">${specialPerson('stella')}\\u003cspan class=\\\"versus\\\">VS\\u003c/span>${['mikoto', 'hiraga', 'rinna', 'tatara'].map(specialPerson).join('')}\\u003c/div>\\u003cdiv class=\\\"dialog-result\\\">史黛菈 · WIN\\u003c/div>\\u003cp class=\\\"dialog-description\\\">${esc(data.special.detail)}\\u003c/p>${evidence(data.special.evidence)}`);\\n  }\\n\\n  function openPlayer(id) {\\n    const route = allMatches.filter(match => match.p1 === id || match.p2 === id);\\n    const refs = [...new Set(route.flatMap(match => match.evidence))];\\n    const identity = data.players[id]?.identityNote;\\n    if (identity) route.unshift({ label: '身份关联 · 原著档案', detail: identity });\\n    showDialog(`\\u003cp class=\\\"dialog-kicker\\\">PLAYER ARCHIVE / 原著参赛记录\\u003c/p>\\u003ch2 id=\\\"dialog-title\\\" class=\\\"dialog-title\\\">${esc(name(id))}\\u003c/h2>\\u003cdiv class=\\\"dialog-duel\\\">${person(id)}\\u003c/div>\\u003cdiv class=\\\"player-route\\\">${route.map(match => `\\u003cdiv class=\\\"route-row\\\">\\u003cb>${esc(match.label)}\\u003c/b>\\u003cspan>${esc(match.detail)}\\u003c/span>\\u003c/div>`).join('')}${['hiraga', 'rinna', 'tatara'].includes(id) ? '\\u003cdiv class=\\\"route-row\\\">\\u003cb>特别赛成员\\u003c/b>\\u003cspan>赢得各自首轮后，加入史黛菈对鹤屋的一对四特别赛；此事不抹去此前的首轮赛果。\\u003c/span>\\u003c/div>' : ''}\\u003c/div>${evidence(refs)}`);\\n  }\\n\\n  function stop() {\\n    clearInterval(state.timer);\\n    state.timer = null;\\n  }\\n  window.RK_MATCH_CANON = { pause() { stop(); render(); } };\\n\\n  function setStage(stage) {\\n    stop();\\n    state.stage = stage;\\n    focusForStage();\\n    render();\\n  }\\n\\n  document.addEventListener('click', event => {\\n    const button = event.target.closest('button');\\n    if (!button) return;\\n    if (button.dataset.view || button.dataset.openRegion) {\\n      stop();\\n      state.view = button.dataset.view || button.dataset.openRegion;\\n      focusForStage();\\n      render();\\n    } else if (button.dataset.display) {\\n      state.display = button.dataset.display;\\n      render();\\n    } else if (button.dataset.focus) {\\n      stop();\\n      state.focus = button.dataset.focus;\\n      state.stage = effectiveRound(matchesById.get(state.focus));\\n      render();\\n    } else if (button.dataset.stage !== undefined) setStage(Number(button.dataset.stage));\\n    else if (button.dataset.match) { stop(); state.focus = button.dataset.match; state.display = 'broadcast'; render(); }\\n    else if (button.dataset.player) openPlayer(button.dataset.player);\\n    else if (button.hasAttribute('data-special')) openSpecial();\\n  });\\n  $('#previous').addEventListener('click', () => setStage(state.stage - 1));\\n  $('#next').addEventListener('click', () => setStage(state.stage + 1));\\n  $('#play').addEventListener('click', () => {\\n    if (state.timer) { stop(); render(); return; }\\n    if (state.stage >= 5 || state.stage === 3) {\\n      state.stage = 0;\\n      if (state.view === 'finals') state.view = 'C';\\n    }\\n    focusForStage();\\n    state.timer = setInterval(() => {\\n      state.stage++;\\n      if (state.stage >= 4 && state.view !== 'all') state.view = 'finals';\\n      focusForStage();\\n      if (state.stage === 5) stop();\\n      render();\\n    }, 1800);\\n    render();\\n  });\\n  $('.dialog-close').addEventListener('click', () => dialog.close());\\n  $('#match-source').addEventListener('click', () => openMatch(state.focus));\\n  dialog.addEventListener('click', event => { if (event.target === dialog && (event.clientX \\u003c dialog.getBoundingClientRect().left || event.clientX > dialog.getBoundingClientRect().right || event.clientY \\u003c dialog.getBoundingClientRect().top || event.clientY > dialog.getBoundingClientRect().bottom)) dialog.close(); });\\n  new ResizeObserver(drawConnectors).observe(board);\\n  render();\\n})();\\n\\n\\u003c/script>\\n\\u003c/body>\\n\\u003c/html>\\n\\n\";\n\n// 赛事子页只接收终端已经选定的 MVU 快照，不另读消息或保存变量。\nvar tournamentPanelFrame = null;\nvar tournamentPanelSource = null;\n\nfunction pushTournamentPanel() {\n  var frame = tournamentPanelFrame;\n  if (!frame || !frame.contentWindow.RK_MATCH_PREVIEW) return;\n  v